cache = {}
for op in ops:
    p = Path(op[1])
    if not p.exists():
        raise SystemExit(f"ERROR: Missing {p}. Run from repo root.")
    if p not in cache:
        cache[p] = p.read_text(encoding="utf-8")

for op in ops:
    kind, path_s = op[0], op[1]
    p = Path(path_s)
    src = cache[p]
    if kind == 'replace':
        old, new = op[2], op[3]
        n = src.count(old)
        if n != 1:
            raise SystemExit(f"ERROR: {p}: expected one match, found {n}.")
        src = src.replace(old, new, 1)
    elif kind == 'append_if_missing':
        marker, text_to_append = op[2], op[3]
        if marker not in src:
            src = src.rstrip() + "\n\n" + text_to_append.strip() + "\n"
    elif kind == 'insert_before_last':
        marker, insert = op[2], op[3]
        idx = src.rfind(marker)
        if idx < 0:
            raise SystemExit(f"ERROR: {p}: closing marker not found.")
        src = src[:idx] + insert + src[idx:]
    cache[p] = src

for p, src in cache.items():
    p.write_text(src, encoding="utf-8")

